head.script:
// 화면 리사이징

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        scwin.init();
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33030.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    if (js_market === "9") {
        rdo_MARKET_TP_CD.setValue('A');
    } else {
        rdo_MARKET_TP_CD.setValue(js_market);
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_FindForm_onclick
 * @description img_FindForm 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_FindForm_onclick = async function() {
    try {
        // *** 셋팅할 필드명 정의를 아래처럼 해야함.
        // => 보고서명: txb_FormNm, 보고서코드 : txb_FormCd
        let url = "/common/ULDSTF91003.gfm";
        const winTitle = "공시제목선택 ";
        await $c.frame.CreateDialogFrame("FORMLIST", url, winTitle, 100, 10, 690, 570, "window");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33030.img_FindForm_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33030.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF33030.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "연계공시대상서식목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33030.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name txb_FormCd_onblur
 * @description txb_FormCd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_FormCd_onblur = function() {
    try {
        if (txb_FormCd.getValue() === "") {
            txb_FormNm.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33030.txb_FormCd_onblur" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33030.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33030.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33030.btn_Close_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    let url = "/LnkDisclsApplCorp.do?method=selectLnkDisclsApplCorp" + "&SEARCH_TYP=LINK_FORM" + "&LD_MKT_TP_CD=" + rdo_MARKET_TP_CD.getValue() + // 시장구분
        "&FORM_CD=" + txb_FormCd.getValue() + "&FORM_NM=" + txb_FormNm.getValue() + "&FORM_SEARCH_CD=" + rdo_FORM_SEARCH_CD.getValue();
    url += "&SCREN_ID=" + "ULDSTF33030.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
